mapper.select:
SELECT DISTINCT d.* FROM t_dish d
INNER JOIN t_dish_tag dt ON d.id = dt.dish_id INNER JOIN t_nutrition_tag t ON dt.tag_id = t.id
WHERE d.status = 1
AND d.name LIKE CONCAT('%', #{keyword}, '%')
AND d.meal_period = #{mealPeriod}
AND t.code IN
#{c}
GROUP BY d.id HAVING COUNT(DISTINCT t.code) = #{tagCount}
ORDER BY d.heat_score DESC, d.id ASC

SELECT d.* FROM t_dish d
INNER JOIN t_dish_tag dt ON d.id = dt.dish_id
INNER JOIN t_nutrition_tag t ON dt.tag_id = t.id
WHERE d.status = 1 AND d.stock > 0 AND d.id != #{excludeId}
  AND d.meal_period = #{mealPeriod}
  AND t.code IN (
    SELECT t2.code FROM t_dish_tag dt2
    INNER JOIN t_nutrition_tag t2 ON dt2.tag_id = t2.id
    WHERE dt2.dish_id = #{excludeId}
  )
GROUP BY d.id
ORDER BY COUNT(*) DESC, d.stock DESC
LIMIT 1
